from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_row = next((r for r in range(1, h - 1)
                    if len(set(grid[r])) == 1), None)
    if sep_row is not None:
        first, second = grid[:sep_row], grid[sep_row + 1:]
        height, width = min(len(first), len(second)), w
    else:
        sep_col = next((c for c in range(1, w - 1)
                        if len({grid[r][c] for r in range(h)}) == 1), None)
        if sep_col is None:
            return grid
        first = [row[:sep_col] for row in grid]
        second = [row[sep_col + 1:] for row in grid]
        height, width = h, min(len(first[0]), len(second[0]))

    bg1 = Counter(x for row in first for x in row).most_common(1)[0][0]
    bg2 = Counter(x for row in second for x in row).most_common(1)[0][0]

    return [[3 if first[r][c] != bg1 and second[r][c] != bg2 else bg2
             for c in range(width)] for r in range(height)]
